0453 | \subsection{Expansion}\label{sec : expansion}
0454 | 
0455 | We now use the cones constructed for $Gr(V)$ to show that $Gr(V)$ has good coboundary expansion. Using cones to prove expansion is a technique developed in the work of Gromov \cite{Gromov} on topological overlap, and was implicitly defined in the work of Meshulam and Wallach \cite{MW}. Since then this technique was further developed and applied in greater generality e.g. \cite{LMM}, \cite{KOStrongSymmetry}.
0456 | 
0457 | We use this technique together with the cone construction of \Cref{sec : homological properties} to prove coboundary expansion of $Gr(V)$.
0458 | 
0459 | We remark that there is small set expansion, meaning that if a chain has a few subspaces then it must expand by simple counting:
0460 | 
0461 | \begin{claim}\label{claim: small-set-expansion}
0462 |     For $\alpha \in C^k(X)$ we have $|d_k \alpha| \geq {n-k \choose 1}_q |\alpha| - |\alpha| \left(  |\alpha|-1 \right)$
0463 | \end{claim}
0464 | 
0465 | \begin{proof}
0466 |     Notice that every subspace in $\spp(\alpha)$ is contained in ${n-k \choose 1}_q$ subspaces of codimension $1$, so the number of subspaces that contain elements from $\alpha$ is at least:
0467 | 
0468 |     \begin{align*}
0469 |         {n-k \choose 1}_q |\alpha| - {|\alpha| \choose 2}
0470 |     \end{align*}
0471 | 
0472 |     Since out of the ${n-k \choose 1}_q |\alpha|$ subspaces we counted, the subspaces that contain $k$ elements from $\alpha$ are counted $k$ times and therefore by subtracting ${|\alpha| \choose 2}$ each such term is counted $ k- {k \choose 2} \leq 1$ times. There is clearly a surjection from ${\spp(\alpha) \choose 2}$ to the subspaces that contain more then one element, therefore:
0473 | 
0474 |     \begin{align*}
0475 |         |d_k \alpha| \geq {n-k \choose 1}_q |\alpha| - {|\alpha| \choose 2} - {|\alpha| \choose 2} \geq {n-k \choose 1}_q |\alpha| - |\alpha| \left(  |\alpha|-1 \right)
0476 |     \end{align*}
0477 | \end{proof}
0478 | 
0479 | 
0480 | 
0481 | \subsubsection{Coboundary expansion}
0482 | 
0483 | We now turn to prove high dimensional expansion of $Gr(V)$. We refer the intrested reader to \Cref{sec : exp by restrictions} for a different inductive argument for expansion of $1$-cochains via a different method of studying the expansion of a cochain by restricting it to a uniformly chosen, codimension $1$ hyperplane. We adapt the language of \cite{LMM}. We start with the following claim:
0484 | 
0485 | 
0486 | \begin{claim}
0487 |     $\iota_s d_k \alpha + d_{k-1}\iota_s \alpha =  \alpha$ where the contraction $\iota_s$ is given by $\iota_s \alpha (W) = \alpha(c_{s,W})$
0488 | \end{claim}
0489 | 
0490 | \begin{proof}
0491 |     Let $W$ be a subspace, then:
0492 | 
0493 |     \begin{align*}
0494 |         \iota_s d_k \alpha (W) + d_{k-1}\iota_s \alpha(W) &= d_k \alpha (c_{s,W})+ \iota_s \alpha (\partial W) \\
0495 |         &= \alpha (\partial c_{s,W}) + \alpha (c_{s,\partial W}) \\
0496 |         &= \alpha (\partial c_{s,W} + c_{s,\partial W})
0497 |     \end{align*}
0498 |     By \Cref{Proposition - Cone Identity} we know this equals to $\alpha(W)$ as required.
0499 | \end{proof}
0500 | 
0501 | \begin{claim}\label{claim : cone bound}
0502 |     Let $\vec{b}$ be any basis and $W$ any $k$ space then: \begin{align*}
0503 |         |c_{\vec{b},W}| \leq [k+1]_q \left( [k]_q!^2 \cdot \left( 1 +  \sum_{j=1}^{k} \frac{1}{[j]_q!^2} \right)\right)
0504 |     \end{align*}
0505 | \end{claim}
0506 | 
0507 | \begin{proof}
0508 | 
0509 |     Let $f(k)$ be a bound of the size of a cone of a $k$ space. By definition, $c_{\vec{b},W}$ is the coboundary of a $(-1)^k \left(W- c_{\vec{b}, \partial W} \right)$ in some $2k+1$ therefore:
0510 | 
0511 |     \begin{align*}
0512 |         |c_{\vec{b},W}| \leq [k+1]_q \left(|W|+| c_{\vec{b}, \partial W}|\right) \leq [k+1]_q \left( 1 + [k]_q f(k-1) \right)
0513 |     \end{align*}
0514 | 
0515 |     Thus,
0516 |     \begin{align}\label{eq : recursive cone bound}
0517 |         f(k) \leq [k+1]_q \left( 1 + [k]_q f(k-1) \right)
0518 |     \end{align}
0519 |     The proof follows since the RHS of the equation in the claim satisfies \Cref{eq : recursive cone bound}, and bounds the cone size for zero dimensional subspace.
0520 | \end{proof}
0521 | 
0522 | \begin{remark}
0523 |     This bound is stronger than the bound $|c_{\vec{b},W}| \leq  { 2k+1 \choose k+1}_q $ by roughly a factor of $q^k$.
0524 | \end{remark}
0525 | 
0526 | \begin{theorem}\label{thm : expansion}
0527 | 
0528 |     Let $h_{k,n}$ be the expansion constant of $k$ cochains of $Gr(V)$ where dim $V=n$. Let $b$ be the bound of the cone size for $k$ chains, and assume $k< \frac{n}{2}$. Then:
0529 | 
0530 |     \begin{enumerate}
0531 |         \item $h_{k,n} \geq  \frac{[n-k]_q}{[k+1]_q} \cdot \frac{1}{b}$, where $b$ bounds the cone size.
0532 | 
0533 |         \item $h_{n-k,n} \geq \frac{1}{b}$.
0534 |     \end{enumerate}
0535 | 
0536 | \end{theorem}
0537 | 
0538 | \begin{proof}
0539 | 
0540 |     For the first item, let $S$ be the set of all bases of $\mathbb{F}_q^n$ then
0541 | 
0542 |     \begin{align*}
0543 |         |S| \cdot  \norm{ [\alpha] } &\leq \sum_{s \in S} \norm{\alpha -  d_{k-1}\iota_s \alpha }  \\
0544 |         &= \sum_{s \in S} \norm{ \iota_s d_k \alpha } \\
0545 |         &\leq \sum_{s \in S} \sum_{W \in Gr(k,n)} \mathds{1}_{d_k \alpha (c_{s,W})\neq 0} \\
0546 |         &\leq \sum_{s \in S} \sum_{W \in Gr(k,n)} \mathds{1}_{\spp(c_{s,W}) \cap \spp( d_k \alpha) \neq \emptyset}
0547 |     \end{align*}
0548 | 
0549 |     By symmetry each element of $Gr(k+1,n)$ will be in the support of $c_{s,W}$ the same number of times over all $s \in S$ and $W \in Gr(k,n)$. This is true in particular for all the elements of $\spp( d_k \alpha)$ therefore we can bound the last term above by $|S|\cdot |Gr(k,n)| \cdot b \cdot \norm{d_k \alpha}$ thus:
0550 | 
0551 |     \begin{align*}
0552 |         |S| \cdot  \norm{ [\alpha] } \leq \frac{|S|\cdot |Gr_{k}(n)| \cdot b}{|Gr_{k+1}(n)|} \cdot \norm{d_k \alpha}
0553 |     \end{align*}
0554 | 
0555 |     Which implies:
0556 | 
0557 |     \begin{align*}
0558 |         \frac{\norm{d_k \alpha}}{\norm{ [\alpha] }}   \geq \frac{ |Gr_{k+1}(n)| }{|Gr_{k}(n)| \cdot  b} = \frac{[n-k]_q}{[k+1]_q} \cdot \frac{1}{b}
0559 |     \end{align*}
0560 | 
0561 |     For the second item, each closed chain $\alpha \in Z_k$ can be filled by $c_{\vec{b},\alpha}$ for some basis $\alpha$ which has size at most $b |\alpha|$. The claim follows by \Cref{Claim - Bilinear form duality}.
0562 | \end{proof}
